// Scene SDF with material IDs
vec2 map(vec3 p) {
    float orbitRadius = 1.5; // Radius of orbit
    float orbitSpeed = 2.0;  // Speed of orbit

    vec3 center = vec3(0.0, 0.5, 0.0); // Center of orbit

    // Sphere 1
    vec3 p1 = center + vec3(orbitRadius * cos(iTime * orbitSpeed), 0.0, orbitRadius * sin(iTime * orbitSpeed));
    float sphere1 = sdSphere(p - p1, 1.0);

    // Sphere 2 (opposite side)
    vec3 p2 = center + vec3(orbitRadius * cos(iTime * orbitSpeed + 3.14159), 0.0, orbitRadius * sin(iTime * orbitSpeed + 3.14159));
