    // Ground plane
    float plane = sdPlane(p);

    // Return closest object with material ID
    vec2 res = vec2(sphere1, 1.0); // Red sphere
    if (sphere2 < res.x) res = vec2(sphere2, 2.0); // Blue sphere
    if (plane < res.x) res = vec2(plane, 3.0); // Gray plane

    return res;
